package com.orderflow.gateway;
import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import org.slf4j.MDC;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.cloud.gateway.filter.*;import org.springframework.core.Ordered;import org.springframework.http.*;import org.springframework.stereotype.Component;import reactor.core.publisher.Mono;import java.nio.charset.StandardCharsets;import java.util.UUID;
@SpringBootApplication public class GatewayApplication{public static void main(String[]a){SpringApplication.run(GatewayApplication.class,a);}}
@Component class SecurityAndCorrelationFilter implements GlobalFilter,Ordered{private final byte[]secret;SecurityAndCorrelationFilter(@Value("${jwt.secret}")String s){secret=s.getBytes(StandardCharsets.UTF_8);}public int getOrder(){return-100;}public Mono<Void>filter(org.springframework.web.server.ServerWebExchange ex,GatewayFilterChain chain){String correlation=ex.getRequest().getHeaders().getFirst("X-Correlation-ID");if(correlation==null||correlation.isBlank())correlation=UUID.randomUUID().toString();var request=ex.getRequest().mutate().header("X-Correlation-ID",correlation);String path=ex.getRequest().getURI().getPath();boolean publicPath=path.startsWith("/api/auth/")||(ex.getRequest().getMethod()==HttpMethod.GET&&path.startsWith("/api/products"))||path.equals("/actuator/health");if(!publicPath){String auth=ex.getRequest().getHeaders().getFirst(HttpHeaders.AUTHORIZATION);try{if(auth==null||!auth.startsWith("Bearer "))throw new IllegalArgumentException();var claims=Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret)).build().parseSignedClaims(auth.substring(7)).getPayload();request.header("X-User-ID",claims.getSubject()).header("X-User-Role",claims.get("role",String.class));}catch(Exception e){ex.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);return ex.getResponse().setComplete();}}return chain.filter(ex.mutate().request(request.build()).build());}}
